@page "/settings"
@rendermode InteractiveServer
@using sv_8f4774b3c09844e3aee1e0590b44eb39.Services
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme</label>
        <select @bind="SelectedTheme">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="SelectedAccentColor" />
        <span style="color: @SelectedAccentColor;">@SelectedAccentColor</span>
    </div>

    <button class="btn btn-primary" @onclick="Save">Save Preferences</button>
</div>

<p class="mt-3">
    Current: <strong>@ThemeService.Theme</strong> /
    <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme { get; set; }
    private string SelectedAccentColor { get; set; } = "#0078d4";

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeService.Update(SelectedTheme, SelectedAccentColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeService.Theme;
            SelectedAccentColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

